export const GLOSSARY: Array<[string, string]> = [
  ['Chips (Idea step)', 'What your words already say about the shot (camera, phone camera, framing, outfit, makeup, place, light), read for free. Click one to change it; what you set wins.'],
  ['Send my prompt as written', 'A pasted prompt goes unchanged, with only the reference line, the 21+ line and the REALISM block added. No writer, no camera, light or outfit lines.'],
  ['More control', 'The collapsed part of the Idea step: character, account, format, places and every detail of the shot.'],
  ['What was sent', 'Under every still and on every failed run: the final prompt exactly as sent, the images and element attached, the model, the path, the settings, the price quoted next to the real cost, and why a failed run failed.'],
  ['Real cost', 'What a run actually took: the credits in your Higgsfield transactions on the plan, the measured tokens for Claude. More than 20% off the quote is flagged.'],
  ['Recreate from a real clip', 'Your character in a real clip: four stills in the clip\'s frame, an optional face pass, then the clip\'s real motion onto the still that passes both face checks.'],
  ['Face pass', 'On a Recreate still, only the face changes to match the character: it edits that still, so the place, outfit, pose and framing stay (one that changed the scene is marked not usable). It runs on the best still with Make 4 stills, and is skipped, not charged, when that still is already clear of the clip\'s person; Fix this face runs it on any other.'],
  ['Scene to keep / Source traits to drop', 'Recreate\'s chips: what of the clip stays (place, light, angle, props) and what of its person never carries over (hair color, eyes, piercings, makeup).'],
  ['Recreate gates', 'Fixed: the video starts only from a still whose face matches REF-00 (0.45 or more), beats its likeness to the person in the clip by a clear margin (0.12 or more), and whose likeness stays under 0.45 (or the numbers you approved in a gate check). A fail says why and offers another take.'],
  ['Gate check', 'After every 10 real recreates, Settings > Rules shows the face and margin scores of the stills you made videos from next to the ones you passed over, and suggests new gate numbers. Suggest only: the numbers change only when you press Use these numbers.'],
  ['Margin', 'On a Recreate still: its face match to REF-00 minus its likeness to the person in the clip. The gate needs 0.12 or more, so a still never passes looking almost as much like the source as like the character.'],
  ['Motion model', 'What moves the still like the clip: Genjutsu, Wan 3.0, Wan 3.0 Prime or Kling 3.0 Motion Control, each on your plan or the API, with its price.'],
  ['Billing path', 'How a run is paid: your Higgsfield plan (credits) or the Higgsfield API (dollars). Each model shows which one it uses.'],
  ['Spend cap', 'The most a recreate post may spend, in credits. A step that would pass it is refused with what is left.'],
  ['Drift marks', 'Red marks on the review strip where the face in the take drops under 0.45 against REF-00, the same number as the video rule.'],
  ['Earlier failures line', 'One gray line in place of a pile of red: how many runs before this one were blocked by the filter (refunded), never ran, or failed, and that nothing was charged. Show lists them; Clear hides them for good. Only the run you just started can be red.'],
  ['Catalog wording', 'Outfits said the way a shop catalog does: garment, color, fabric, a style word ("dark green ribbed tank top with thin straps, going-out look"). No fit or body words (busty and cup sizes included), "bike shorts" for "boy shorts" (every other garment name stays), a moment instead of a pose. Only the words change, never what she wears; your own words go as typed. The lists are config/wording.yaml.'],
  ['Likely trigger words', 'After a refusal by the provider\'s filter: the words in what was sent that filters often block (fit or body words, cup sizes, "boy shorts").'],
  ['Template check', 'A character file checked against character template v1.6, for free, in the Import dialog and under the character file: the UNIVERSAL sections, the age (21 or older), one distinguishing mark, REF-00 to REF-11 labeled, and the Element ID when one is named. Missing optional sections and leftover [brackets] are listed. It never blocks an import.'],
  ['Update (re-import)', 'Importing a file for a character that is already here: the file\'s words replace the old ones; posts, takes, stills and the sheet stay, the combo log is merged, every saved identity is kept, and identical sheet images are skipped.'],
  ['Brand card', 'The first card on a character\'s Character file step: the brand layer of the file (brand statement, series, running bits, cast, accounts, winning stack, growth log), edited in place and saved back into the file.'],
  ['Winning stack', 'What the top reels of the last monthly growth review share. Every post carries it for the next 30 days: the prompt writer, the planner and Punch it up get it, inside the fixed rules.'],
  ['Brand check', 'Punch it up checks each of its three moments against the brand statement; one that does not fit says "Off brand" and why. Advice only.'],
  ['Makeup by setting', 'A default: no makeup at home, the gym, an early beach or waking up; soft everyday makeup out in public; soft glam for nights out and events. A character\'s own everyday makeup line replaces the soft everyday wording. Men get groomed brows and beard, never makeup words. Your choice or your words win.'],
  ['Hair rotation', 'A default: each new scene starts with the next hair styling from the bank, never one used in the character\'s last 5 combo log entries or scenes. Color and texture stay the character\'s. A styling you type or name in the idea wins. The bank is config/scenes.yaml.'],
  ['Name the garment', 'A warning on the Recreate stills price when the outfit the clip reader wrote names no garment type ("black top" gets drawn as a plain tee). Read the outfit again (priced) reads the outfit only and names it. Never on your own words; a default in Settings > Rules (outfit-garment). The garment list is config/wording.yaml.'],
  ['Retry with safer wording', 'The refused run again with only its trigger words reworded by code ("tight" out, "boy shorts" to "bike shorts"). The rewording is free; the run is priced like the one that was refused.'],
  ['No caption', 'A choice next to White box and Outline: no caption track in the editor and none in the export. Kept with the post; switch back any time and the words return. A caption is never required anyway: an empty one means no caption.'],
  ['Studio picker', 'What Add media opens in the editor: this post\'s takes and stills, the character\'s clips and stills, then the Library. Tap adds at the playhead; drag puts it on a track. From computer is its second tab.'],
  ['Kept as uploaded', 'An uploaded image is stored as the very same file: full resolution, never downscaled, recompressed or converted. Only the small copy for the grid is made from it.'],
  ['Viewer', 'Any still or clip full size, one tap from its thumbnail anywhere in the Studio: arrows or a swipe for the next one, its name, date, character, model, cost and the posts that use it, Download and the place\'s own use button. Only the open one loads the full file.'],
  ['Collection', 'A named set of Library items (stills and clips of any character): Select, then Add to collection. The Collection filter shows only its items. Deleting a collection never deletes its items.'],
  ['Trash', 'Where a deleted item waits 7 days (Library > Trash). Restore puts it back; after 7 days the daily clean removes its files from storage for good, small copies included.'],
  ['Auto-clean', 'Takes you never kept and stills you never picked go to the Trash 14 days after their post is finished (Settings, General, Storage: 3, 7, 14 or 30 days, or Off). Never sheet refs, heroes, a character file, kept or starred takes, anything a post uses, what a kept take was made from, or saved Library clips. The first run waits for Start Auto-clean in its Preview.'],
  ['Next auto-clean', 'In Settings, General, Storage: how many items the next Auto-clean would move to the Trash, with Preview to see each one and star any to keep.'],
  ['Star (a take)', 'The star next to a take\'s name (and on each item in the Auto-clean preview). A starred item is never auto-cleaned; a kept take counts as starred.'],
  ['Daily clean', 'Once a day on the worker (free): upload slots never used after a day, the Trash past its 7 days, Auto-clean, and the storage measure. Opening Posts home starts it when it is due.'],
  ['Storage readout', 'Settings, General, Storage: your files in storage in GB and the estimated monthly cost at $0.015 per GB-month, the first 10 GB free.'],
  ['Export for', 'A preset per app (TikTok, Reels, Shorts) in the Finish step: a length cap, a bitrate cap and the loudness the sound ends at. It applies to Export, the editor\'s Done and the hook variants. The numbers are config/content.yaml.'],
  ['Hook variants', 'Up to 3 versions of the same video, each with a different first 2 seconds: a hook line in place of a caption there, a different first shot (a take, still or clip from the Studio), a camera preset as the first edit, or any of them. Free, on the worker.'],
  ['Cover', 'A frame of the exported video, picked by scrubbing, with optional cover text in the caption look: a 1080 x 1920 JPEG to upload as the cover.'],
  ['Safe zones', 'In the editor\'s top bar: where TikTok or Reels draw their own top bar, buttons and caption area, drawn over the preview. Preview only, never exported.'],
  ['Speed marker', 'In the editor, a marker on the Presets track for a freeze or a speed ramp. Click it to open the Speed panel for that shot.'],
  ['Timeline', 'The post as one timeline: its shots, B-roll, captions, presets and sound. The Studio lays it out; the editor changes it.'],
  ['The editor', 'OpenReel, full screen over a post: place presets on the timeline, trim, move, retime. Done exports, saves to the post and returns.'],
  ['Edit in place', 'In the editor, double-click a caption (in the preview or on the timeline) to change its words where it sits. Enter saves, Esc cancels.'],
  ['Karaoke captions', 'A preset that lights up a caption\'s words one after another across the caption, in the Studio\'s yellow. The caption keeps its place, look and words.'],
  ['Ducking', 'The music dips under the voice line (or the clip\'s own sound) so the words stay clear. The editor applies it when a post opens.'],
  ['Ends with the last shot', 'In the editor, a caption or music that ended with the last shot keeps ending with it when the shots change length (speed, trim, delete), so the export stops with the video, not on black.'],
  ['Video rule', 'How a Recreate take is read: the stills\' numbers over the whole take (middle face match, middle margin, highest likeness). A take that misses is a warning with Keep this take and Try again, never thrown away.'],
  ['Preset', 'An edit you drop on the timeline at the playhead (a crash zoom, a speed ramp, karaoke captions): drag it, trim it, set its strength, change its keyframes.'],
  ['Continue this shot', 'Make the next take from the last frame of a clip, then join them into one longer clip.'],
  ['Shot B', 'The second shot of a two-shot edit (crash zoom cut, whip pan, hand over the lens, zoom-rotate spin), right after the clip; for split screen it plays beside or below it.'],
  ['Person mask', 'Her outline in every frame, made free on the worker, for text behind her, the green screen and the dolly zoom.'],
  ['Saved style', 'The presets on a timeline, saved with places like "at the payoff" or "on beat 4", so one click puts them on another post. Make another like this carries the post\'s own.'],
  ['Beat sync', 'Beats of the music (found by the editor, tapped or typed) shown on the timeline; clips and presets snap to them. The music can stay in the export or not.'],
  ['Payoff', 'The moment the video builds to. The editor can suggest it as a marker; you place presets on it with one click.'],
  ['Room tone', 'The quiet sound of a room, made by code. The default ambience; a silent video sounds dead.'],
  ['LUFS', 'How loud a video sounds overall. Posts are normalized to -14, like TikTok, Reels and Shorts play them.'],
  ['REF-00', 'The hero face. Every later image copies it.'],
  ['Reference sheet', 'REF-00 to REF-11: the same person from every angle, with expressions and full body.'],
  ['Still', 'A photo of a moment, made in a post\'s Stills step.'],
  ['Take', 'A video made from a still. Use this take keeps it.'],
  ['Clip', 'Any kept video: a take, an upload or a clone. It lives in Library > Clips.'],
  ['Clone', 'A saved TikTok or Reel rebuilt with your character.'],
  ['B-roll', 'A screen recording or phone video cut in before or after the clip.'],
  ['Director\'s notes', 'The writer\'s choices that make a shot memorable: the moment, the hook, the payoff, one camera move, depth, light, one contrast. Edit them and Rewrite follows them.'],
  ['REALISM block', 'The real-skin line added to every image prompt. Always on.'],
  ['Free checks', 'The face match against REF-00 and the skin check. They run on every still, take and clone.'],
  ['Check this', 'Claude looks closely at one result (marks, sides, logos, skin). Priced, on demand.'],
  ['Demo / Live', 'Demo makes free mock results. Live uses your real accounts and costs money.'],
  ['Plan credits / API', 'Higgsfield billing: your own account\'s credits, or the pay-per-use API.'],
  ['Fixed rule / default', 'Fixed rules always apply. Defaults are pre-filled and you can switch them off.'],
  ['Account tag', 'Which social account a post is for, like "Callie TikTok". Posts home filters by it.'],
  ['Voice card', 'How a character talks: point of view, words used and never used, emoji, humor, pillars, an example line, and their ElevenLabs voice. The writers follow it.'],
  ['Voice line', 'One line you performed, turned into the character\'s voice with every word timed. Library > Voice lines.'],
  ['Voiceover', 'A voice line laid over a video post, with the music and ambience dipping under it and captions from its words.'],
  ['Hook vault', 'A product\'s numbered opening lines, grouped by type. Library > Hooks.'],
  ['Hook pattern', 'What kind of hook it is: someone doubts or reacts, POV, things nobody tells you, red flags, listicle, storytime, myth vs fact, tier list. Every hook a slideshow writes is tagged with one.'],
  ['Use this hook', 'On a slideshow: drafts every slide from the hook, one story thread (setup, the turn, the payoff, relief or a question last), each with the image line its photo shows, plus the caption. Priced, a small Claude call.'],
  ['Product', 'What a post is for (SideStep, a brand deal, anything you promote), or No product. Picked in the Idea step; a new post takes its account\'s. The product brings its vault, claims sheet and the rules it adds; nothing of it reaches another product\'s posts.'],
  ['General standard', 'How every post is written, any product or none: the stop test (a stranger would stop, clear on one read, says exactly what happened, sounds like a person), one story thread, every slide clear to a stranger, an image line a slide, the voice from the character\'s voice card or the account. A product can add its own rules on top.'],
  ['One camera roll', 'A slideshow\'s locked scene: the same place, light, phone, outfit and 2 details in every photo, so the set looks like one day\'s photos.'],
  ['Scene library', 'Saved slideshow scenes (place, light, camera, 2 details) for a character or a topic. Pick one in any slideshow and the same room looks the same every time.'],
  ['Special slide', 'A mock screen drawn by code, free: a notification, a text thread, a rejection email, a job posting, an application form, a portal status timeline, a calendar invite, an invoice or receipt, a bank or savings app, a museum placard, a 0 to 10 survey, a lock screen or a profile card. Generic names only; a real brand becomes a generic name.'],
  ['Text style', 'How a slideshow\'s words look: Classic (bold white, black outline), Text box, Minimal or Note. Dragged words keep their place, and the export draws exactly what the preview shows.'],
  ['Variation family', 'A slideshow and the variations made from it (variation_of), each with new words, new pictures and a new caption for another account.'],
  ['post.json', 'In every slideshow zip, and next to a video post\'s MP4: every field of the post (slides or the video, words, pictures, scene, caption, hashtags, CTA line, #ad, account, family) and its plan row, for the posting engine.'],
  ['Structure or lens code', 'S1 to S12 (Levels, Two Characters, Untold Story, Is It Worth It?, Testing Viral Hacks, Teaser, Jenga carousel, Visual Metaphor, Man on the Street, Challenge series, Contrast pair, Countdown) and L13 to L25 (frames like Museum exhibit, Invoice, Group chat): the shape a hook and its slides are poured into (the viral writing playbook).'],
  ['Effect', 'E1 to E8: what the viewer should feel, on slide 1 and at the payoff ("That\'s literally me", "Wait, what?", "I need to know how this ends", "LMAO", "Sending this to someone", "So it\'s not me", "I never saw it that way", "Screenshotting this").'],
  ['Hook score', '1 (best) to 5. On the general standard, the writer\'s own rank (it keeps only hooks that pass its stop test). On SideStep posts, the ladder (playbook v1.2: 1 is plain, painful, an open loop, plus a sharp specific or twist; 5 is a topic, a label or a headline), from a separate reviewer that runs the stop test first; only a 1 or 2 ships.'],
  ['THE STANDARD', 'SideStep\'s rules for slide 1, on top of the general standard, on SideStep posts only (viral writing playbook v1.2, its top section): it names the job situation, says exactly what happened, hurts 7 or more out of 10, reads in one second with no image (about 15 words), opens a loop the slides close, in the voice of your friend in the group chat. Moments, structures and lenses shape slides 2 to 6. Slideshows are TikTok only.'],
  ['Stop test', 'The first check on every hook. The general standard\'s four: would a stranger stop; is it clear on one read; does it say exactly what happened; does it sound like a person, not a brand? SideStep adds two (clearly about a job; pain 7 or more) and a separate reviewer that runs it; any no is a 3 at best, so it is hidden.'],
  ['Product ending', 'On a SideStep ad (#ad on), slide 6: a friend\'s tip that fixes the exact slide 1 pain, from the four honest endings only (fills the app in one click, shows the match before you apply, shows what to add from things you did, $99 once). Pains SideStep does not fix stay pure pain, with no mention.'],
  ['Alt hook', 'The runner-up hook kept with a post. Swap with the alt hook trades them in one tap; Make variations starts from it.'],
  ['Language notes', 'Free warnings under hooks, slides and captions. Long dashes on every post; the rest are SideStep\'s rules, on SideStep posts only (should and must, "just" before an instruction, hustle words, a sentence that starts with "You", too many hashtags, the product in a hook, "Ad:" on product captions, no job word and the rest). Never a block.'],
  ['Launch plan', 'Posts > Launch plan: the plan\'s CSV previewed for free, then the rows you tick become drafts for the plan\'s product with their words as written; Generate N posts makes the pictures ten posts at a time.'],
  ['Product screenshot', 'A special slide that places your own uploaded screenshot of the product. The Studio never draws a product screen.'],
  ['Variant', 'A hook rewritten in one character\'s voice, so accounts never post the same line.'],
  ['Claims sheet', 'What you can say about a product, and what never to say. Anything about the product stays inside it.'],
  ['Buyer language', 'Real phrases buyers use, collected from comments and reviews. The writers use them instead of marketing words.'],
  ['Scoreboard', 'Posts home > Accounts: accounts ranked by signups from their tracked link or promo code, never by views.'],
]

export const sectionById = (id: GuideId): GuideSection => GUIDE.find(s => s.id === id)!
